#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""Generate original scenes showing distant illumination and bounded fog."""
import argparse
from pathlib import Path

from generate_spot_samples import box, diffuse, header, sphere


def scene_header(eye, target, integrator, args):
    return header(eye, target, integrator, args.samples, args.width, args.height).replace(
        'spotlight sample; generated by generate_spot_samples.py',
        'distant-light sample; generated by generate_distant_samples.py')


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output-dir', type=Path, default=Path('build/distant-samples'))
    parser.add_argument('--samples', type=int, default=512)
    parser.add_argument('--width', type=int, default=768)
    parser.add_argument('--height', type=int, default=512)
    args = parser.parse_args()
    if not 1 <= args.samples <= 1048576 or args.samples & (args.samples - 1):
        parser.error('--samples must be a power of two from 1 through 1048576')
    if not 1 <= args.width <= 4096 or not 1 <= args.height <= 4096:
        parser.error('--width and --height must be from 1 through 4096')
    args.output_dir.mkdir(parents=True, exist_ok=True)
    s = scene_header((7, 4.2, -9), (0, 1, 2), 'path', args)
    s += 'LightSource "distant" "point3 from" [-3 6 -3] "point3 to" [0 0 3] "blackbody L" [5500] "float illuminance" [3]\n'
    s += 'LightSource "infinite" "rgb L" [.35 .55 1] "float scale" [.1]\n'
    s += diffuse((.24, .28, .33)) + box((-10, -.12, -6), (10, -.06, 12))
    s += diffuse((.12, .14, .19)) + box((-8, -.06, 8), (8, 5, 8.1))
    s += diffuse((.6, .29, .13)) + box((-2.7, -.05, 1.5), (-1.2, 1.7, 3))
    s += 'Material "coateddiffuse" "rgb reflectance" [.65 .69 .74] "float roughness" [.2]\n'
    s += sphere((.2, .95, 2.2), 1)
    s += 'Material "conductor" "rgb reflectance" [.8 .55 .24] "float roughness" [.22] "bool remaproughness" [false]\n'
    s += sphere((2.2, .7, 3.3), .75)
    (args.output_dir / 'afternoon-studio.pbrt').write_text(s)

    s = scene_header((7.7, 3.6, -9), (0, 2, 2.5), 'volpath', args)
    s += 'LightSource "distant" "point3 from" [-5 7 -4] "point3 to" [0 0 4] "blackbody L" [4500] "float illuminance" [4]\n'
    s += 'LightSource "infinite" "rgb L" [.2 .4 1] "float scale" [.025]\n'
    s += 'MakeNamedMedium "haze" "string type" "homogeneous" "spectrum sigma_a" [360 .012 830 .012] "spectrum sigma_s" [360 .1 830 .1] "float g" [.35]\n'
    s += 'AttributeBegin\nMaterial "interface"\nMediumInterface "haze" ""\n'
    s += box((-6, 0, -2), (6, 6, 9)) + 'AttributeEnd\n'
    s += diffuse((.23, .27, .33)) + box((-9, -.12, -5), (9, -.06, 12))
    s += diffuse((.08, .1, .15)) + box((-9, -.06, 8), (9, 7, 8.1))
    s += diffuse((.05, .06, .08))
    for x in (-4, -2.5, -1, .5, 2, 3.5):
        s += box((x, 4.5, -2), (x + .32, 4.8, 5))
    s += 'Material "coateddiffuse" "rgb reflectance" [.62 .64 .68] "float roughness" [.24]\n'
    s += sphere((0, .95, 3), 1)
    (args.output_dir / 'sunlit-fog.pbrt').write_text(s)
    print('Generated afternoon-studio.pbrt and sunlit-fog.pbrt')


if __name__ == '__main__':
    main()
